    "booth": "3701",
    "description": "Albert Moy is also the original artwork sales representative for some of the greatest comic book artists in the industry today. Albert is entrusted by Jim Lee, Bruce Timm, Sam Kieth, Jae Lee, John Cassaday, The Estate of Darwyn Cooke, J Bone, Erik Larsen, Peter Snejbjerg, Scott Williams, Michael T. Gilbert, Sandu Florea, Michael Cho, Mario Foccillo, Chrissie Zullo,and Chris Uminga to bring their artwork to fans and collectors.\n\nAlbert has been in the hobby of collecting and selling comic book artwork since 1984 and his wealth of knowledge is known throughout the hobby to help you acquire that unique piece for your collection. Albert's knowledge can also help you get the best price for your collection if you ever want to consign your art. Not only does he have an online presence, but he also takes and displays the artwork at major comic conventions throughout North America.\n\nThe artwork for sale and trade on this site is representative of just a small fraction of the artwork Albert collects. If you have original artwork to sell or trade please email me at albertmoy@aol.com or call (718) 225-3261",
