    "specials": [
      {
        "id": "63926",
        "title": "The Art of Link Click: Moments Book 2",
        "description": "The world of Link Click, a beloved donghua, couldn’t be confined to a single art book. Therefore, a second volume dedicated to the newer seasons of the series is here.\n\nThis volume takes readers on a journey through new locations, intricately designed characters, atmospheric background art, concept illustrations, storyboards, and exclusive behind-the-scenes materials. It showcases the evolution of the visual world of Link Click, from familiar characters presented in a fresh perspective to new faces, dramatic scenes, and the artistic choices that shaped the story’s continuation.\n\nFor those who felt one journey into the world of Link Click wasn’t enough, this volume offers even more illustrations, production materials, and behind-the-scenes content. It serves as an invitation to delve deeper into the captivating vortex of Link Click, expanding the horizons of this fandom.",
        "price": "45.00",
        "link": "https://aloha.store/collections/pre-orders/products/the-art-of-link-click-moments-book-2"
      },
      {
        "id": "63933",
        "title": "Ever After Vol. 1. 9781638380801",
        "description": "Ever wondered what comes after the so-called \"Happily Ever After\"? Brothers Jacob and Wilhelm don't have to: they make their living cleaning up the messes left behind by those whose fairytales didn't end quite where you were told.\n\nFrom acclaimed manga creator Ikuno Tajima comes After Märchen, a hauntingly beautiful fantasy that reimagines the world beyond classic fairy tales.",
        "price": "19.00",
        "link": "https://aloha.store/collections/pre-orders/products/ever-after-vol-1"
      }
    ],
