    "name": "Art and Design High School",
    "booth": "3861",
    "description": "Art and Design is a vibrant school that offers hands-on training in commercial and digital arts including animation, architecture, cartooning, fashion, film, graphic design, illustration and photography. Students participate in paid internships in the industry and earn professional certifications in a range of skills, including Adobe Photoshop, Adobe Premiere, and AutoCad to name a few. The school, which attracts diverse students from across the city, offers strong academics including advanced and college level courses as well as support for students needing extra help.\n \nFounded in 1936, Art and Design counts many prominent figures among its alumni including Tony Bennett, Harvey Fierstein, Calvin Klein, Art Spielgelman, Marc Jacobs, and Devon Rodriguez. Many of its teachers are working artists and the school's industry partners and network of loyal alumni provide a steady stream of internships and employment opportunities for students and graduates.",
