    "name": "Bandai Namco Entertainment America Inc.",
    "booth": "2319",
    "description": "Bandai Namco Entertainment America Inc. is part of the Bandai Namco Group, a leading global publisher and developer of interactive entertainment known for creating beloved game franchises such as PAC-MAN®, GALAGA®, TEKKEN®, and ACE COMBAT®, and publishing the critically acclaimed DARK SOULS™ series and the blockbuster title ELDEN RING™.\n\nBandai Namco Entertainment America Inc. is also the publisher in the Western hemisphere for popular anime-based video games including GUNDAM™, NARUTO SHIPPUDEN™, DRAGON BALL™, and ONE PIECE®.",
