    "booth": "2401",
    "description": "Dragon Ball is returning to NYCC for the first time in two years! The Dragon Ball Special Booth will bring together an exciting lineup of Dragon Ball content, including toys, games, and more!\nBe sure to stop by booth #2401 and join the fun—we can’t wait to see you there!\n\nABOUT DRAGON BALL\nThe globally beloved manga DRAGON BALL by Akira Toriyama continues to captivate fans through a wide range of media—from TV animation, movies, games, and merchandising—standing as a top-ranked title with extraordinary worldwide popularity. Now, in 2026, the anime Dragon Ball Super, based on Akira Toriyama's original work, story, and character design, is set to begin anew as Dragon Ball Super: Beerus!\nThis ENHANCED edition introduces a large volume of newly added and redrawn cuts, as well as a reconstructed narrative. With cutting-edge visual expression, the series delivers even more immersive battle scenes and a more faithful representation of the original manga—bringing an ENHANCED edition to life like never before. Learn more about Dragon Ball Super: Beerus at https://dragonball-super.com/en/index.html",
