    "name": "Chocolate Moonshine Co., LLC.",
    "booth": "4529",
    "description": "For almost 30 years, Chocolate Moonshine has delighted customers with the original, federally protected recipes created by Chris Warman Sr. Our award-winning Truffle Bars, Gourmet Fudge, Pecan Caramel Explosions, and Artisan Chocolate Bars are crafted from the world's finest ingredients, including Belgian and French chocolate, Madagascar vanilla, and pure cane sugar. Made using traditional methods and uncompromising standards, our confections have elevated the art of fudge-making worldwide. Treat yourself to award-winning Chocolate Moonshine creations and discover why customers keep coming back for more.",
