    "description": "For over 30 years, Choice Fine Art has been the leader in pop culture art. \nOriginal Animation Art, Comic Art, Limited Edition Prints and Rare Collectibles.\nAs holders of one of the largest animation archives in the world, Choice Fine Art specializes in offering our collectors the original hand-painted cels and animators drawings that were used to create classic TV shows and feature films. Represented studios include Disney, DC Comics, Warner Bros., Hanna-Barbera, Lucasfilm and Marvel among others. Whether you are a new art buyer looking to make your first print purchase, or a seasoned art collector building upon your collection, we are here to help! Each work is expertly packed and shipped and guaranteed authentic with a studio certificate of authenticity.\n\n Choice is dedicated to delivering the highest-quality collectible artworks with museum-quality framing at the best prices.",
