    "description": "The Civics for All Comics Group began in early 2020 as a collaboration between the New York City Public Schools and various comics creators to publish non-fiction graphic texts for educational use. Spearheaded by the Department of Social Studies & Civics, the imprint has published forty-four comics and printed over six million floppies as of July 2026. We are proud to be one of the top ten largest comic publishers in the United States. In addition to publishing comics, the Civics for All Comics Group regularly presents at conferences and freely shares its resources to educators and schools throughout the country. Visit us at NYCC to check out our free NYCC Exclusives!",
