    "name": "Comic Spot",
    "booth": "3653",
    "description": "Welcome to Comic Spot, your ultimate destination for bringing pop culture to life through a curated collection of comic exclusives, enamel pins, Loungefly mini backpacks, crossbody bags, accessories, and must have collectibles.\n\nAt Comic Spot, we believe fandom isn’t just a hobby, it’s a lifestyle. That’s why we specialize in the most iconic and beloved worlds of Disney, Star Wars, Marvel, Pokémon, and beyond, offering everything from stylish Loungefly bags and collectible enamel pins to exclusive variant comics you won’t find anywhere else.\n\nLooking for something truly special? We’re proud to offer convention only comic exclusives, limited-edition enamel pins, and comic blind bags packed with surprises perfect for collectors, casual readers, and anyone looking to discover their next favorite issue.\n\nWhen you shop with Comic Spot, you’re not just buying collectibles you’re joining a community of passionate fans. Whether you’re a die hard Disney devotee, a Jedi in training, a Marvel superhero, a Pokémon Master, or a comic collector chasing your next big find, Comic Spot is your go to source for exclusive fandom gear and unforgettable convention pickups.",
