        "title": "G.I. Joe: A Real American Hero / Tomb Raider #1 Peter Smith Trade Dress NYCC Exclusive",
        "description": "NYCC 2026 Exclusive – G.I. Joe: A Real American Hero / Tomb Raider #1 – Peter Smith Trade Dress Variant\n\nTwo legendary franchises collide in G.I. Joe: A Real American Hero / Tomb Raider #1, featuring an exclusive NYCC 2026 Trade Dress Variant from Comic Spot with cover art by Peter Smith.\n\nThis limited-edition cover brings Lara Croft together with iconic members of the G.I. Joe and Cobra universe in Peter Smith’s distinctive style, created especially for New York Comic Con.\n\nLimited to only 750 copies.\n\nAvailable at NYCC 2026 Booth #3653 while supplies last.",
        "price": "20.00",
