        "id": "63927",
        "title": "Venom Inc. Omega #1 Dell’Otto 2\" Enamel Pin- NYCC 2026 Exclusive",
        "description": "NYCC 2026 Exclusive – Venom Inc. Omega #1 Dell’Otto 2\" Spider-Man Enamel Pin\n\nSpider-Man swings into NYCC 2026 with this Venom Inc. Omega #1 2\" Enamel Pin, available exclusively from Comic Spot!\n\nInspired by Gabriele Dell’Otto’s cover artwork for Amazing Spider-Man: Venom Inc. Omega #1, this collectible pin captures Spider-Man in Dell’Otto’s dramatic style.\n\nProduced as a Comic Spot Exclusive and limited to only 300 pieces, this officially licensed Marvel collectible is a standout addition for Spider-Man fans, Dell’Otto collectors, and comic-inspired enamel pin collectors.\n\nAvailable at Comic Spot – Booth #3653 during New York Comic Con 2026, while supplies last.",
