    "description": "We are a professional plastic toy manufacturer providing comprehensive one-stop OEM & ODM manufacturing solutions.\n\nAll production procedures are completed in our own factory with independent dedicated workshops: 3D modeling, 3D prototyping, tooling, injection molding, spray painting, pad printing, wash effect finishing, assembly and packaging.\n\nOur factory is certified with NBCU, FAMA, Sedex, ISO9001 and ISO14001. We strictly adopt eco-friendly and biodegradable raw materials for all productions to meet global environmental standards.\n\nOur core product lines cover character figurines, resin statues, food-grade plastic packaging containers, electronic toys, activity play sets, toy cars and more customized plastic merchandise for licensed brands and global clients.",
