    "description": "At Hit Parade, we create themed, curated collectible products for fans and collectors. From trading cards and sports memorabilia to TCG, comics, and more, every release is carefully built by our team with a focus on quality, value, and the excitement of the chase. We source cards, signed memorabilia, and unique collectibles from across the hobby, then thoughtfully curate each release to create products that balance incredible chases with fun everyday hits. Whether you're discovering Hit Parade for the first time or have been collecting with us for years, our goal is to build products that we're proud to put into the hands of fellow collectors.",
