    "description": "Derrick Smith is a self-taught traditional artist, specializing in oil on canvas for portraits, landscapes, and a variety of concepts both of his own imagination, as well as from pop culture. Residing just outside of Pittsburgh, Pennsylvania, Derrick creates in his home studio, a space he has truly made his own.\n\nPainting since 2006, Derrick's style is rather unique; his paintings are mostly grayscale with elements of color dripping from his subjects, hence the moniker he has been using since beginning his career: Death of Color. Over the years, his technique has flourished and evolved into something truly exceptional.",
