    "id": "nycc-exhibitor-664629",
    "officialId": "664629",
    "name": "Department of Lore Inc.",
    "booth": "3325",
    "description": "MAYA is an expansive narrative universe built by filmmaker Anand Gandhi (Ship of Theseus, acclaimed for its inquiry into identity and consciousness) and game designer Zain Memon (creator of SHASN, the bestselling board game that makes complex systems of power playable). Over five years, they've built a world grounded in the first principles of evolution, ecology, and economics, which now unfolds across books, games, films, and graphic novels.\nMAYA: Seed Takes Root became the most funded debut novel on Kickstarter ahead of its global launch through Simon & Schuster. Esquire calls it “a narrative superstructure that rewires storytelling.” Neuroscientist Anil Seth calls it “a book of extraordinary riches, both sweeping and immersive.” \nCome meet the creators and pick up a signed copy of one of 2026’s most anticipated SFF novels at our booth.",
