    "id": "nycc-exhibitor-670306",
    "officialId": "670306",
    "name": "Dice Dungeons",
    "booth": "4234",
    "description": "Dice Dungeons is a tabletop RPG publishing and accessory company founded by two lifelong gamers at their weekly D&D game. Since 2016, we’ve been creating the tools we want at our own table—from uniquely designed dice to immersive GM resources like our Quest Decks and 5e-compatible books like: Mutated Monsters, 80s Adventures, and P.T Lamark's Cryptid Codex. Our products include luxury dice in resin, metal, gemstone, and glass; monster tokens; condition rings; portable battle maps, and character coins. Everything we make is designed to help players and game masters create unforgettable adventures.\n\nIn addition to bestselling gear, we’ve published over 20 Quest Decks filled with system-agnostic side quest hooks, and continue to expand our book line with bold new projects like our ‘80s Adventures RPG supplement and Cryptid Codex. Whether you’re a veteran DM or a first-time player, we aim to make your next game more fun, flavorful, and easy to run.",
    "website": "https://dicedungeons.com/",
