    "description": "Welcome to the Galactus Booth — Your Destination for Trading Cards & Collectibles\n\nCalling all collectors, players, and trading card enthusiasts!\n\nWhether you're hunting for the perfect card, upgrading your collection, or looking to sell, Galactus is your one-stop destination for trading cards at New York Comic Con.\n\nFrom the latest releases to legendary collectibles from the past, our booth brings together an incredible selection of cards from across the TCG world.\n\n What You'll Find at Our Booth:\n\nCards from Your Favorite TCGs\nExplore a huge selection of singles and collectibles from the biggest trading card games, including Magic: The Gathering, Pokémon, Yu-Gi-Oh!, One Piece Card Game, Disney Lorcana, and more.\n\nRare & High-End Collectibles\nLooking for something special? Discover sought-after cards, premium editions, iconic pieces, and hard-to-find collectibles for every type of collector.\n\nFoils, Promos & Special Editions\nFrom stunning foils and exclusive promos to limited releases and unique versions, our showcases are packed with cards designed to stand out in any collection.\n\nVintage & Old-School Treasures\nTake a trip through trading card history with vintage cards, nostalgic favorites, and hard-to-find pieces from some of the most iconic TCGs ever released.\n\nCompetitive & Playable Cards\nPlayers are welcome too! Find staples, upgrades, and powerful cards to improve your decks across multiple games and formats.\n\nLooking to Sell Your Cards? Bring Them to Galactus!\n\nGalactus isn't just a place to buy —we're buying too.\n\nOur experienced international buying team will be on-site throughout New York Comic Con, ready to evaluate your cards and collections and make fair, competitive offers on the spot.\n\nWhether you're selling a handful of cards, high-end collectibles, or an entire collection, our goal is to make the process fast, professional, and transparent.\n\nTo make selling even easier, we'll offer:\n\nWhy Visit Galactus?\n\nAt Galactus, trading cards are more than just a game — they're a passion, a hobby, and a world of collecting.\n\nWhether you're a longtime collector, a competitive player, a casual fan, or discovering TCGs for the first time, there's something waiting for you at our booth.\n\nBuy. Sell. Trade. Collect. Discover.\n\nCome meet the Galactus team, explore our showcases, and find your next favorite card.\n\nDon't miss us at New York Comic Con — visit the Galactus Booth and experience the world of trading cards!",
    "website": "https://x.com/GalactusTcg",
    "storeUrl": "https://x.com/GalactusTcg",
    "featured": false,
    "showSpecials": true,
    "exclusives": true,
    "sourceUrl": "https://www.newyorkcomiccon.com/en-us/exhibitors-and-artists/exhibitors.html",
    "sourceKind": "official-feed"
