    "description": "Global Girls Squad is a media company founded by author Dina C. Tate, creating edutaining and inspiring stories for young girls ages 5–9. Its flagship chapter book series, Lizzie & McKenzie’s Fabulous Adventures, celebrates friendship, individuality, adventure, leadership, and the importance of embracing what makes each of us unique.\nImagine if all the little girls of the world looked alike. If the Same Glam Goddess gets her way, they will. McKenzie Rivers, a pint-sized daredevil, and Lizzie Sanders, who loves all things frilly, are called upon by Princess Lovina of Exquisite City to stop her. Armed with magical lovely lockets and fierce diva weaponry, the girls must travel the world in search of the Seven Crystals of Sisterhood before the Same Glam Goddess can erase the identities of little girls everywhere. Their first adventure takes them to the magical city of Madrid.",
