    "name": "Guy Gilchrist",
    "booth": "2057",
    "description": "Guy Gilchrist is a Connecticut-born cartoonist, illustrator, writer, and musician. Known as Jim Henson's Cartoonist, Gilchrist was chosen to create Jim Henson's Muppets newspaper comic strip from 1981 to 1986. He was instrumental in other Henson projects such as Muppet Babies, Fraggle Rock, and more.\n \nGilchrist has also worked for Disney, Warner Brothers, and MGM Studios. He has headed publishing and/or licensing for TMNT, Tom and Jerry, Looney Tunes, Tiny Toons, Pink Panther, Minnie Mouse, Ariel, and more.\n \nNot to be forgotten are the hundreds of books that his studio has had a creative hand in. He personally wrote and illustrated an additional 60+ children's books which have been recognized by organizations such as the National Cartoonists Society, International Reading Council of the United Nations, and Publisher's Weekly Magazine.",
