    "description": "Hachette Book Group (HBG) is a leading U.S. general-interest book publisher made up of dozens of esteemed imprints within the publishing groups Basic Books Group, Grand Central Publishing, Hachette Audio, Little, Brown and Company, Little, Brown Books for Young Readers, Orbit, Running Press Group, and Workman Publishing. We also provide custom distribution, fulfillment, and sales services to other publishing companies. Our books and authors have received the Pulitzer Prize, National Book Award, Caldecott Medal, Newbery Medal, Booker Prize, Nobel Peace Prize and other major honors. We are committed to diversity in our company and our publishing programs, and to fostering a culture of inclusion for all our employees and authors. We are proud to be part of Hachette Livre, the world's third-largest trade and educational publisher.",
