    "name": "Hake's Auction",
    "booth": "3318",
    "description": "HAKE'S AUCTIONS: AMERICA'S FIRST POP CULTURE COLLECTIBLES AUCTION HOUSE, SINCE 1967! HAKE'S AUCTIONS IS THE PREMIER AUCTION HOUSE FOR EVERYTHING FROM AMERICANA AND POLITICAL CAMPAIGN MEMORABILIA TO THIRD-PARTY GRADED ACTION FIGURES, TOYS, PLAYSETS, SPORTS AND NON-SPORTS TRADING CARDS AND MORE! CHECK OUT OUR BOOTH AT NYCC 2026!\n\n🚨 Special Guest Alert! Hake's Auctions is excited to host renowned comic book artist Joe Staton for a special booth signing on Saturday (10/10) from 1:00 PM to 3:00 PM at NYCC 2026. Be sure to stop by for this fantastic opportunity to meet a comics legend! ✨",
    "website": "WWW.HAKES.COM",
    "storeUrl": "WWW.HAKES.COM",
    "featured": false,
    "showSpecials": true,
    "exclusives": true,
    "sourceUrl": "https://www.newyorkcomiccon.com/en-us/exhibitors-and-artists/exhibitors.html",
