    "name": "Hand Over The Hero",
    "booth": "2580",
    "description": "Tony Poulson is the artist behind the popular \"Hand over the Hero\" series, a fan favorite at comic conventions and art festivals worldwide for nearly 13 years. His distinctive style puts a quirky and cute spin on pop culture by featuring iconic characters being \"handed over\" by their counterparts or allies. This charming approach appeals to fans across all genres.\n\nWe offers a wide range of products, including original art, on-site framed prints, and premium vinyl stickers. He also creates limited-edition designer toys officially licensed by major names in the industry, such as Nickelodeon and Bob Ross.",
