    "name": "Insight Editions",
    "booth": "3319",
    "description": "Celebrated for its deep dedication to quality, Insight Editions is a bestselling publisher of books and collectibles that push the boundaries of creativity, design, and production. Through its licensed publishing program, Insight Editions produces unique books and products that provide meaningful ways to engage with characters and stories. Insight Editions' award-winning art and photography titles celebrate the artistry and history of a wide range of subjects, from rock to film to nature conservation. Insight Editions' New York Times bestsellers include Bowie: Stardust, Rayguns & Moonage Daydreams, Henry Winkler's I've Never Met an Idiot on the River, and Radhanath Swami's The Journey Within. Recent national bestsellers include Friends: The Official Cookbook, Harry Potter: Knitting Magic, and The Elder Scrolls: The Official Cookbook. Insight Editions manifests its dedication to sustainability and conservation through publishing partnerships with organizations such as Jane Goodall Institute, The National Parks Association, Mission Blue, and Roots of Peace.",
