    "booth": "3259",
    "description": "La Meno is all about jewelry that feels special, wearable, and a little magical. We create high-quality pieces in sterling silver, gold filled, and stainless steel, with designs inspired by anime, celestial details, magical-girl energy, cute characters, and the fandoms we love.\n\nWe love creating jewelry that lets you show off your personality and favorite things in a way you can still wear every day , whether you’re heading to a convention, dressing up, or just adding a little sparkle to your everyday look. \n\nAnd there’s more to come! La Meno has an upcoming collaboration with Bananya in the works!",
