    "name": "Landry Pop Auctions",
    "booth": "3552",
    "description": "Landry Pop Auctions (LPA) is a vibrant new auction brand tailored for modern collectors passionate about comics, toys, pop culture, and more! Led by Travis Landry, former star of Toy Hunter and a fixture on Antiques Roadshow since 2018, LPA combines encyclopedic knowledge with a deep passion for discovering and presenting exceptional material.",
