    "description": "Lifeline Comics is a Ringo Award-winning New York-based comic publisher founded by Kat Calamia & Phil Falco.\n\nAs a company founded by queer creators, we're dedicated to publishing comics across a wide range of genres with an emphasis on diversity and inclusiveness.\n\nYou may know us from our WEBTOON \"Slice of Life\", our comic anthologies (Bi Visibility, Transphoria, Rainbow Canvas, and the Ringo-Nominated Hairology), or from our many creator-owned series.\n\nKat was a member of the first Kickstarter Advisory Council and we release the majority of our titles first through Kickstarter campaigns.",
