    "description": "Rod Van Blake is a Marine veteran turned scifi and fantasy author. Ancient Illumination is his science fiction series. The first title debuted in 2016 with follow up novels releasing in 2018, and 2020. During the pandemic he also began collaboration with artist Jordan Jackson to adapt this first series into graphic novels. Nyumbani Chronicles the Return Home is his fantasy debut which was released in 2021. The sequel Nyumbani Chronicles II Draconian Tribunal was released in 2023. The Ancient Illumination: Amissio Membri comic mini-series first issue was published in March of 2026, and he is currently working on the third novel in the fantasy series with early 2027 as a target for its release. If you're into first contact, military action space opera, or epic fantasy tales in either literary or illustrated forms come to table W-5 in writer's block!",
