    "booth": "3839",
    "description": "🚨 MBartist x Groundbreaking Comics — NYCC 2026! 🚨\n\nNext stop: Booth 3839 at New York Comic Con!\n\nWe’ll be bringing a few key releases with us while supplies last, including:\n\n🔥 All 3 Marvel Comics Midnight launches\n🔥 Oni Press — Sabrina #1\n🔥 BOOM! Studios — Something Is Killing the Children #50\n🔥 A selection of MBartist Exclusive releases\n🔥 Plus as many long boxes packed with comics as we can possibly squeeze into the booth.\n\nOne of this year’s featured MBartist releases will be the G.I. JOE: A Real American Hero / Tomb Raider #1 — Raiders of Cobra Island NYCC Exclusive, featuring cover art by Steven Ahola.\n\nCopies will be available at the booth and can also be signed and remarqued by Steven Ahola during the show.\n\nIf you’re heading to NYCC, make sure to stop by Booth 3839, dig through the boxes, check out the exclusives, and say hello.\n\nWe hope to see you in the madness! 🗽🔥\n\nMBartist x Groundbreaking Comics\n📍 New York Comic Con — Booth 3839",
