    "officialId": "670160",
    "name": "MISS SUNSHINE NAILS INC",
    "booth": "2987",
    "description": "Miss Sunshine Nails is a New York City–based handmade press-on nail brand bringing wearable art, creativity, and self-expression to your fingertips. Every set is carefully designed and hand-painted by our in-house nail artists, with styles ranging from cute and colorful to bold, edgy, character-inspired, and highly detailed 3D designs. Our work has been featured by Vogue, NBC, Business of Fashion, and at New York Fashion Week, among others. With 1,000+ real customer reviews and a community of 150K+ followers across social media, Miss Sunshine Nails has become a trusted destination for unique, high-quality press-on nails.\nFounded in NYC in 2022, Miss Sunshine Nails has grown from a small local business into a destination for nail lovers, K-pop fans, anime and cosplay enthusiasts, and anyone looking for something more unique than traditional press-on nails. We also have a permanent retail location in Manhattan’s Koreatown, where customers can shop our collections in person. Our reusable designs are available in a wide variety of shapes, lengths, and sizes from XS to XL, making it easier for everyone to find the right fit and style.",
