    "booth": "3221",
    "description": "At Out of Print, we turn favorite stories into fashion statements. Our bookish merchandise goes far beyond the classics—celebrating readers of every genre with thoughtfully designed high-quality products made in collaboration with beloved artist and authors.\n\nWhether you're a lifelong horror fan, a nostalgic fantasy devotee, or discovering your next romantic obsession, we make it easy to wear your fandom on your sleeve—literally. Tees, totes, hats, pins, and more-- check us out!",
