    "name": "Paper Lab Studios",
    "booth": "1945",
    "description": "Here at Paper Lab Studios, we specialize in one-of-a-kind fast, fresh art! No request is too big or too small, and we'll get your commission done that day. We also mail artwork out if it's more convenient for you. \n\nWe have original comics for sale to scratch that Indie Comics itch, and our booth offers a variety of prints ranging from small to large size, so be sure to stop by since there's something for everybody.",
