    "name": "Plastic Empire",
    "booth": "2478",
    "description": "Plastic Empire is your destination for limited-edition designer toys, collectibles, artist collaborations, and convention exclusives. At New York Comic Con, we’re bringing an incredible lineup of exclusive releases and limited collectibles created with some of the most exciting artists and designers in the collectible community.\n\nVisit Plastic Empire to discover exclusives featuring Abominable Toys’ Godzilla x Chomp, Dungeon Crawler Carl, Bearly, Jimmy, and Frozen Culture Godzilla, along with special releases and collaborations from an outstanding lineup of artists, including Tom Whalen, Benjamin Su, Jason Rowe, Andrew Heath, Connor McConnell, TJP, LabMonkeys, 5th Turtle, Revise D., Are-Jay Designs, and Star Wars Joshua.\n\nFrom kaiju and designer toys to artist-driven collectibles and ultra-limited convention releases, Plastic Empire is bringing something special for collectors to discover at NYCC.\n\nStop by, check out the exclusives, meet the Empire, and find your next must-have collectible.\n\nWelcome to the Empire.",
