    "name": "Pro Wrestling Tees",
    "booth": "4643, 4647",
    "description": "Pro Wrestling Tees is the leading direct-to-consumer merchandise provider for professional wrestlers, wrestling promotions, and fans around the world. Launched in 2013 and headquartered in Chicago, Illinois, the company has revolutionized the way wrestling merchandise is produced, distributed, and sold, creating a vital revenue stream for independent and mainstream wrestling talent alike.\n\nThrough its innovative print-on-demand platform, Pro Wrestling Tees empowers hundreds of active and legendary wrestlers from the indie circuit to global promotions like AEW and NJPW to design, sell, and profit from their own merchandise without the overhead and risk of traditional retail. With over 2 million orders shipped globally, the company has established itself as a cornerstone of the wrestling fan economy, offering a diverse catalog of t-shirts, hats, pins, collectibles, and exclusive limited-run items.\n\nIn addition to supporting wrestlers directly, Pro Wrestling Tees is the official merchandise partner of All Elite Wrestling (AEW), Ring of Honor (ROH), Major League Wrestling (MLW), New Japan Pro Wrestling (NJPW), CMLL, and several legacy brands. The platform also serves fans through unique collaborations, event-exclusive releases, and a physical retail presence at high-profile conventions and events.",
