    "name": "Quirkilicious",
    "booth": "1181",
    "description": "Drake (Winson) Tsui (Known as \"Quirkilicious\") is a Canadian freelance illustrator professionally in the field for 10+ years.\n\nSpecializing in 2D splash/front-art paintings, he's been featured by prominent companies such as Bioware and freelanced for Riot Games, more recently creating works for Upperdeck(Marvel) and Blizzard Entertainment.\n\nAlso a sequential artist & writer, he's the creator of of \"SIN\" a 50+ chapter Manga that was published under Inkblazers. Also in 2018 he created \"ePRO\", a webcomic on WEBTOON Canvas and Tapastic.\n\nHis artwork expresses his passions as a pop/geek culture enthusiast. Featuring a wide range of Video games, Cartoons, Anime, Film... and more!",
