        "id": "61137",
        "title": "Inari's Dream Foil - Ruby Art Exclusive",
        "description": "An original Ruby Art illustration created as a special New York Comic Con exclusive. Inspired by the mystical beauty of Japanese folklore and shrine culture, this piece captures a quiet, dreamlike atmosphere with a sense of protection, mystery, and spiritual elegance.\n\nLimited copies available only while supplies last.",
        "price": "50.00"
