    "name": "Ruyikoi",
    "booth": "1829",
    "description": "Ruyikoi isn't just another apparel brand. We create Otaku streetwear like you've never seen before. As an independent brand with a self-sustaining supply chain, we blend traditional culture with Otaku aesthetics to craft truly one-of-a-kind designs.\n\nOur signature collection features reversible sukajan jackets, intricately embroidered denim jackets, and bold, original pieces that stand out in any crowd. Every design is 100% unique, and meticulously crafted to ensure top-tier quality.",
