    "officialId": "668695",
    "name": "SIGNATURE STUDIOS",
    "booth": "4641",
    "description": "Where pop-culture history becomes collectible.\n\nSignature Studios creates rare, artistic collectibles produced in limited editions and exclusively autographed by the iconic talent who helped create the characters, worlds, and culture we love.\n\nOur collection brings together original creators, artists, performers, and voices—including Tom Kenny, Derek Drymon, Kevin Eastman, Craig Bartlett, Susie Lewis, E.G. Daily, DJ Lance Rock, Van Partible, and more.\n\nFrom limited-edition art prints and artist-designed pieces to rare signed collectibles and convention exclusives, every Signature Studios release is created with an emphasis on authenticity, artistry, scarcity, and cultural legacy.\n\nMeet the legends. Collect the legacy.",
    "featured": false,
    "showSpecials": true,
    "exclusives": true,
    "sourceUrl": "https://www.newyorkcomiccon.com/en-us/exhibitors-and-artists/exhibitors.html",
