    "name": "Simon & Schuster",
    "booth": "3425",
    "description": "Simon & Schuster is a global publisher dedicated to sharing a broad range of works that educate, entertain, and inspire readers of all ages. We publish books that represent many perspectives in order to stimulate readers' curiosity and intellectual exploration, inform and challenge perspectives, and help create change in the world. \n\nJoin us at New York Comic Con for a selection of exciting titles and author appearances. From epic Fantasy and imaginative Science Fiction to steamy Romance and chilling Horror - adults, teens, and children - we have something for everyone! Check out our schedule to catch up with your favorite authors at panels and book signings.",
