    "name": "Snowbright Studio",
    "booth": "1857",
    "description": "Snowbright Studio publishes magazines for gamers. Our monthly magazines contain no AI and no advertisements. Plus, you get a Steam key for a videogame included with every volume. \n\nCozy Companion is our magazine for cozy gamers; full of art, recipes, crafts, fiction, as well as reviews of cozy tabletop and video games. Every month will also come with a code for a cozy game we love! \n\nGrim Omen is our magazine for fans of horror, dark sci-fi, and dark fantasy. Enjoy first looks and exclusive access to the latest in dark gaming and film. If you love Cyberpunk, Hades, and horror movie binges, then Grim Omen is made for you! Subscribers also receive a dark Steam game in their inbox every month.\n\nCome meet previous Cozy Companion cover artist Abi Toads at our booth from noon to 5pm on Friday. Then, come meet Grim Omen cover artist Michael Blank at our booth from 11am to 4pm on Sunday.",
