    "name": "SOULX Co., Ltd.",
    "booth": "3341",
    "description": "SOULX is a creative group that brings new culture, art, and experiences to life through XR-based technology, guided by the motto of providing freedom of space and expression to storytellers around the world.\nWe develop immersive content and solutions optimized for the AI era, enabling diverse forms of storytelling—spanning digital content, games, branding, and exhibitions—rooted in unique concepts and worldviews enhanced by cutting-edge XR technology.\nOur core goal is to create an environment where anyone can freely create and communicate.\nSoul X is accelerating a new era where storytelling through video and XR is no longer constrained by traditional production barriers. As AI technology becomes more accessible and digital perspectives shift, content creation is no longer reserved for professionals—anyone can now be a creator.\nTo support this evolution, Soul X is building an open-source ecosystem tailored to the generative AI era, making it easier than ever for creators to produce XR content and express their stories with freedom and creativity.",
