    "description": "STUDIOKM is the illustration studio of artist Kirk Manley. Kirk's work combines realism with comic book styling, creating uniquely powerful interpretations of both established and original characters. His work has been featured on many pop culture sites like io9 and Geek Tyrant. His Walking Dead Episode Tribute art hangs in the writing offices of the AMC hit show. Kirk is a regularly featured artist on the pop culture Convention circuit and has had work published by DC Comics, ScoutComics, ComixTribe, and many more. His popular self-published comic Z-Girl and the 4 Tigers can be purchased online at indyplanet.com \nFor more information visit www.studiokm.com",
