    "name": "Sukesha Ray",
    "booth": "3943",
    "description": "Sukesha Elizabeth Ray, otherwise known as “Sushi” to most, is not who you would call your average artist. She not only wields a pencil, but also a microphone. A dual talent in the game of art and music, she transcends the line of both. \n\nMoving to one of the most direct hotspots for art, her artwork was starting to create some buzz: celebrities reached out to her for her work, she started to get featured in blogs and magazines, started painting huge murals, and even started collaborating with many different brands. She was even featured in Art Basel as a solo female artist twice (Muses Show, and Spectrum respectively). Her style is unique, with avant-garde techniques incorporating her anime, pop culture style into high end pieces that truly bewildered people.",
