    "name": "TAKEONE COMPANY",
    "booth": "3341",
    "description": "Founded in 2016, TakeOne Company has built a global business centered on K-pop IP games. Starting with BTS WORLD and continuing through titles such as BLACKPINK THE GAME, NCT ZONE, and ENHYPEN WORLD, we have expanded the boundaries of the industry—opening up a new fandom-based user market that reaches beyond the traditional gamer audience. We see content not merely as a creative work, but as a doorway and a signpost to new worlds, with the goal of delivering fresh experiences to audiences everywhere.",
