    "specials": [
      {
        "id": "61282",
        "title": "Staffer Retro : A supernatural Mystery Quest",
        "description": "Staffer Retro: A Supernatural Mystery Quest is a visual novel deduction adventure set in a world where supernatural powers are part of everyday life. Follow Verita Retro as she investigates the hidden truths behind past incidents by examining documents, connecting over 100 clues, resolving contradictions, and making choices that lead each mystery toward a different conclusion.",
        "price": "29.99",
        "link": "https://store.steampowered.com/app/3837350/Staffer_Retro/"
      }
    ],
