    "name": "Tee No Evil",
    "booth": "2873",
    "description": "We formed Tee No Evil in 2013. \n\nOur passion for art started when we were kids. We watched horror movies and played video games together – we appreciated the creativity behind the scenes.\n\nOur fascination with art has led us to design tees that people are proud to wear and bring back great memories. We push ourselves out of the comfort zone by trying new techniques. We believe this gives our designs a unique and fun experience!\n\n Our promise has always been to create shirts that our supporter can wear over and over.\n\nTo this day, we make sure our tees are screen printed so the colors will pop. We print on comfy, soft, high quality 100% ringspun cotton for long time wear.\n\nWe offer 100% customer satisfaction.",
