    "booth": "1955",
    "description": "James C. Mulligan is a renowned American artist celebrated for his work with Disney and his dynamic contributions to the world of fine art and pop culture. Known for his vivid, emotionally rich paintings, Mulligan has brought to life beloved Disney characters and scenes, blending classical techniques with a modern sensibility. Beyond Disney, his portfolio includes work in theatre set design, commercial illustration, and collaborations with major brands such as RSVLTS, Lexus, Coca Cola, Disney Lorcana, Walt Disney Comics, Upper Deck, and many others. Mulligan's art has been showcased in galleries worldwide, and his charismatic live painting performances have captivated audiences across the globe, solidifying his reputation as both a gifted visual storyteller and an engaging entertainer.",
