    "name": "The Art of Mark Dos Santos",
    "booth": "1958",
    "description": "Unleash the monsters and embrace the tradition! Stop by to explore a colossal collection of original Kaiju art prints featuring titans like Godzilla, Mothra, Ghidorah, and Gamera. Alongside these epic beasts, discover beautiful Asian folklore art, exclusive collectible coasters, and premium pins. We are incredibly excited to be joined by Zen Calligraphy art, who will be crafting stunning, custom live calligraphy scrolls right at the booth. Whether you are looking for massive monster vibes or elegant, personalized tradition, we have something unique for your collection!",
