    "name": "The Pink Lotus Company LLC",
    "booth": "1471",
    "description": "The Pink Lotus Company is a pop culture crystal company where fandom, spirituality, storytelling, and style collide.\n\nWe create high-quality crystal jewelry and collectibles inspired by the characters, movies, music, television, books, and iconic moments that live in pop culture. From beautifully crafted crystal jewelry and mystical accessories to tarot decks with a pop-culture twist, every piece is designed to bring a little more magic and personality into your world.\n\nOur collection also extends beyond crystals and jewelry with pop-culture books that dive into the stories, icons, trends, and fandoms that have shaped generations. Whether you're a dedicated collector, a lifelong fan, a crystal lover, a tarot enthusiast, or simply someone who appreciates beautifully made things with a story behind them, there’s something here for you.\n\nThe Pink Lotus Company is a celebration of crystals, fandom, nostalgia, magic, and the stories we never stop loving.",
