    "name": "Toy Temple Collectibles, LLC",
    "booth": "2473",
    "description": "Toy Temple is a premier destination for pop culture collectibles, specializing in some of the hottest and most sought-after convention exclusives in the industry. From limited-edition collectibles and exclusive figures to plush, pins, and special releases, we work with leading brands to bring products you won’t find anywhere else. Visit Toy Temple at NYCC to shop our newest exclusives, limited drops, and must-have collectibles before they’re gone!",
    "website": "www.TheToyTemple.com",
    "storeUrl": "www.TheToyTemple.com",
