    "name": "Toynk Toys LLC",
    "booth": "1153, 3462",
    "description": "Our Story:\nBack in 2001, tired of the boring corporate grind, a group of friends hatch a brilliant plan to develop a company centered on fun products. What couldn't be more enjoyable than a business selling costumes, toys and collectibles? The Toynk Toys team has since grown and varies from 40 to 200+ diverse, fun-loving people, depending on the season.\n \nWe've Come a Long Way, Baby:\nToynk Toys has come a long way since its humble inception, operating from a small apartment in Chicago. Today, our Gilberts, Illinois location boasts a 285,000 square foot facility, which is home to our offices and warehouse. Visit us at one of the 200 toy shows/Comic-Cons we attend worldwide yearly.\n \nOur Peeps, Our Philosophy:\nToynk Toys aims to deliver an ever expanding array of cool costumes, trendy toys and hot collectibles to you, our valued customers. Our team comes together each day, working hard to improve our customers' experience. It's not really considered work, when we know that our products bring adventure, joy and happiness to life. It's no wonder that we love what we do and we love doing it for you. Thank you for shopping with us!",
