    "officialId": "664744",
    "name": "Unknown Comics",
    "booth": "3753",
    "description": "Unknown Comics is the Exclusive Comic Book Dealer! We will have show exclusives and talent at the booth. Meet X-MEN VOICE ACTORS Chris Potter (voice of Gambit and Cable) and Cal Dodd (voice of Wolverine) We have 46 exclusives! Absolute Batman, Witchblade, Gi Joe x Tomb Raider, Transformers and more! Exclusive keychains and pins. \n\nMYSTERY BOXES BUILT FOR NYCC! Don't miss out on these special items!",
