        "title": "Amazing Fantasy Classic Pin NYCC 2026 | Classic | Unknown Comic Books Exclusive",
        "description": "3\" Enamel NYCC Amazing Fantasy Classic Pin — New York Comic Con Exclusive\nA celebration of comics history in the palm of your hand. This premium 3\" hard enamel pin pays homage to the iconic Amazing Fantasy cover that introduced the world to Spider-Man — reimagined as a must-have New York Comic Con exclusive for collectors who know their classics.\n\nCrisp enamel fill, bold linework, and a polished finish make this pin as display-worthy as it is wearable. Whether it's going on your jacket, your bag, or straight into the collection box, this is one for the true believers.\n\n3\" hard enamel pin\nNew York Comic Con Exclusive\nCollector-quality finish\nSecure pin-back clasp\nEstimated shipping date: October 28, 2026. Shipping dates are subject to change.",
