    "id": "nycc-exhibitor-664606",
    "officialId": "664606",
    "name": "Vault Comics",
    "booth": "4253, 4351",
    "description": "Vault is a critically acclaimed entertainment company that curates bold new science fiction, fantasy, and horror stories. We have been committed to working with historically underrepresented talent since day one. Purpose-built to create enduring fans, our expansive catalog of more than ninety original titles attracts a diverse and growing fandom. Launching new stories first as comics and graphic novels, Vault has partnered with leading companies like A&E, BET, Boatrocker, Confluential, CBS, Netflix, Paramount, and others, to adapt its story properties to film, television, video games, and more. In 2025, Vault launched BIG RIG, a new comic book series and story universe created by Post Malone, developed together with Michael Bay and Brad Fuller's Platinum Dunes. Also in 2025, together with Aethon Books, Vault will launch Aethon & Vault, a new imprint devoted to bringing the biggest independent science fiction and fantasy novels titles to booksellers everywhere. In 2024 Vault launched Headshell, a line of graphic novels in collaboration with some of the world's most iconic recording artists like Metallica, Def Leppard, the Beach Boys, Fall Out Boy's Pete Wentz, Redman, Slash, and more. Vault titles are distributed everywhere through Simon & Schuster.",
