        "description": "From the creative team of Will Jack, Davis Rider and Simone Ragazzoni - Sweet Death #1 NYCC 2026 Exclusive Cover by Ariel Diaz\n\nVirgin Limited to 200\nFoil Virgin Limited to 100\n\nAssassin with a heart of gold, Eve Killjoy, enters the story, guns blazing. Bound by an unforgiving pact, she must claim 100 souls to earn her freedom, with each kill pulling her further from the life she’s always wanted. What began as a means of survival slowly becomes something much more dangerous, blurring the line between who she is and what she’s becoming. Forced down a violent path she never chose, she must decide how much of herself she’s willing to lose.",
