    "description": "With two locations right outside the nation's capital, Victory Comics is here to meet the comic and gaming needs of the Washington Metropolitan area with our 3500 square feet of retail and in-store gaming space at our flagship location in Falls Church, VA. \n\n Victory Comics can provide cataloging and appraisal of your comics for insurance and other purposes\n\nVictory Comics is also your premier source for back issues -- featuring the most extensive back issue comic inventory in the Washington Metropolitan area. Our decade-long experience as a convention seller has allowed us to assemble an impressive back issue inventory that spans the entire history of comic-dom. Victory Comics is fully equipped and ready to help you build the comic collection of your dreams!",
