    "description": "Hal Jay Greene writes graphic novels that read like a Shakespearean comedy of errors, but with more robots. Blending high-stakes drama with sharp wit, the Colorado-based author crafts stories where every twist feels like destiny and every laugh hides a lurking shadow. Teaming up with Joel Ojeda of Marvel and DC fame, the powerhouse team mix incredible story with beautifully full-colored art resulting in graphic novels you can't put down.",
