    "officialId": "664953",
    "name": "Visual Vibration",
    "booth": "1949",
    "description": "Visual Vibration is an independent comic book publishing house founded and published by Paul Thayer, home to original series including Project Naosis, Hybrid, Sota, Omega 2090, Crimson Payne, and Lethal Leopard. Visual Vibration brings together creators and artists to build an expanding universe of original characters, stories, and comics.",
    "website": "www.projectnaosis.com",
    "storeUrl": "https://www.projectnaosis.com/shop",
