    "specials": [
      {
        "id": "62540",
        "title": "MERCER TRADING CARD | OFFICIAL NYCC EXCLUSIVE",
        "description": "MERCER — NYCC EXCLUSIVE\n\nFirst Print Trading Card of Mercer, who makes his debut in Project Naosis 7!\n\nMercer is a brand new enhanced villain with powerful energy absorption abilities and one of the newest threats to enter the Project Naosis universe.\n\nDon’t miss out on this NYCC Exclusive, limited to only 500 cards, each featuring the official NYCC logo.\n\nFirst Print. NYCC Exclusive. Limited to 500.",
        "price": "5.00"
      },
      {
        "id": "62541",
        "title": "GRIFFIN TRADING CARD | OFFICAL NYCC EXCLUSIVE",
        "description": "First Print Trading Card of Griffin, a brand new superhero making his debut in Project Naosis 7 as a member of the Fifth Frontier!\n\nThe Fifth Frontier is a new superhero team rising in a world filled with death, determined to prove that there is another path besides killing. Griffin possesses the extraordinary ability to use 100% of his brain, making him one of the most unique new heroes in the Project Naosis universe.\n\nDon’t miss out on this Official NYCC Exclusive, limited to only 500 cards, each featuring the official NYCC logo.\n\nFirst Print. NYCC Exclusive. Limited to 500.",
        "price": "5.00"
      },
      {
        "id": "62701",
        "title": "PROJECT NAOSIS 4 | WRAPAROUND COVER | OFFICIAL NYCC EXCLUSIVE",
        "description": "PROJECT NAOSIS 4 | OFFICIAL NYCC EXCLUSIVE WRAPAROUND COVER\n\nProject Naosis 4 kicks off Volume 2 and is a new reader friendly jumping on point into the Project Naosis Universe!\n\nThis massive full color wraparound cover by Luke Dockery features the COVER DEBUTS of DAMA and Darkness Crimson Payne alongside fan favorites Hybrid, Helcate, Lethal Leopard, Omega, Crimson Payne and more. This special cover also celebrates indie comics by bringing in guest characters from other incredible IP, including Overkiller, Black Bull, Hope Breaker, Harriet Tubman Demon Slayer, Killer Bee, Limerence and Buffo! An entire lineup of heroes, villains, and indie comic characters brought together on one massive wraparound cover.\n\nOFFICIAL NYCC EXCLUSIVE\n\nAvailable at NYCC at Visual Vibration Booth 1949 on the main floor.\n\nCover Art by Luke Dockery",
        "price": "20.00"
      },
      {
        "id": "63598",
        "title": "SOTA | OFFICIAL NYCC EXCLUSIVE ASHCAN",
        "description": "SOTA | OFFICIAL NYCC EXCLUSIVE ASHCAN\n\nEnter the world of SOTA with this special 12 page preview ashcan, created exclusively for New York Comic Con!\n\nGet your first look at the newest series from Visual Vibration before the full first issue launches.\n\nTHE TEAM\nCo-Writer & Letterer: Nate “Speed Sultan” Nielsen \nCo-Writer: Brandon “Cozmik Collector” Gingell \nArtist: Ellis Hambyger \nEditor: Paul Thayer\n\n12 Interior Pages \nOfficial New York Comic Con Exclusive \nFirst SOTA Ashcan \nLimited to Only 500 Copies\n\nAvailable exclusively at New York Comic Con, Visual Vibration Booth 1949, while supplies last.",
        "price": "20.00"
      }
    ],
